import React from "react";

const ageGroups = [
  {
    id: "2-5",
    title: "Little Explorers",
    age: "Ages 2–5",
    color: "from-purple-500 to-purple-700",
    image: "/images/little-explorers.png",
    items: ["Memory", "Matching shapes", "Tap the animal", "Sounds & emotions"],
  },
  {
    id: "6-8",
    title: "Play & Learn",
    age: "Ages 6–8",
    color: "from-blue-500 to-blue-700",
    image: "/images/play-learn.png",
    items: ["Quizzes", "Math games", "Word puzzles", "Hospital games"],
  },
  {
    id: "9-12",
    title: "Smart Games",
    age: "Ages 9–12",
    color: "from-green-500 to-green-700",
    image: "/images/smart-games.png",
    items: ["Logic puzzles", "Timed quizzes", "Adventure learning", "Help the doctor"],
  },
  {
    id: "13-18",
    title: "Challenge Zone",
    age: "Ages 13–18",
    color: "from-violet-600 to-violet-800",
    image: "./public/assets/images/games/brain.png",
    items: ["Brain games", "Strategy games", "Quizzes", "Relax games"],
  },
];

export default function Games() {
  return (
    <div className="p-8">
      <h1 className="text-4xl font-bold mb-2 flex items-center gap-2">🎮 Games</h1>
      <p className="text-gray-500 mb-8">Choose your age group and start playing!</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {ageGroups.map((group) => (
          <div
            key={group.id}
            className="relative rounded-3xl overflow-hidden shadow-xl transform transition hover:scale-105"
          >
            {/* Фоновая картинка */}
            <img
              src={group.image}
              alt={group.title}
              className="w-full h-64 object-cover"
            />

            {/* Полупрозрачная панель с текстом */}
            <div className={`absolute inset-0 bg-gradient-to-t ${group.color} bg-opacity-70 flex flex-col justify-end p-6`}>
              <h2 className="text-sm text-white mb-1">{group.age}</h2>
              <h3 className="text-2xl font-bold mb-3 text-white">{group.title}</h3>

              <ul className="text-sm text-white mb-4 space-y-1">
                {group.items.map((item) => (
                  <li key={item}>• {item}</li>
                ))}
              </ul>

              <button className="bg-white text-gray-800 hover:bg-gray-200 px-6 py-2 rounded-full font-semibold transition self-start">
                Play Games
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
